function icon(name){return `<svg viewBox="0 0 ${name==='kakao'?'40 40':'24 24'}" aria-hidden="true">${paths[name]||paths.chat}</svg>`}
const APPS=[['phone','전화'],['messages','메시지'],['contact','연락처'],['calendar','캘린더'],['clock','시계'],['camera','카메라'],['gallery','갤러리'],['internet','인터넷'],['kakao','카카오톡'],['bubble','bubble'],['music','YT Music'],['youtube','YouTube'],['notes','Samsung Notes'],['recorder','음성 녹음'],['files','내 파일'],['settings','설정'],['playstore','Play 스토어'],['google','Google'],['naver','NAVER'],['maps','지도'],['calculator','계산기'],['mail','Gmail'],['health','Samsung Health'],['store','Galaxy Store'],['chrome','Chrome'],['drive','Drive']];
function appIcon(id){if(id==='calendar')return '<span class="cal-icon-head">금요일</span><span class="cal-icon-day">23</span>';if(id==='google')return 'G';if(id==='naver')return 'N';if(id==='calculator')return '±';if(id==='drive')return '<span style="font-size:34px;color:#33a85c">△</span>';if(id==='chrome')return '<span class="chrome-icon"></span>';return icon(id==='messages'?'chat':id==='contact'?'person':id==='maps'?'map':id)}
function appButton(id,label=false){let name=APPS.find(a=>a[0]===id)?.[1]||id;return `<button class="app-button" aria-label="${esc(name)}" onclick="openApp('${id}')"><span class="app-icon ${id}">${appIcon(id)}</span>${label?`<span class="app-label">${esc(name)}</span>`:''}${id==='kakao'&&!allRead?'<span class="badge">1</span>':''}</button>`}
function legacyProfile(id){return `<span class="profile ${id}">${['yechan','wonsang','gwangil'].includes(id)?'':id==='group'?'L':id==='manager1'?'M1':id==='manager2'?'M2':id==='company'?'M':id==='self'?'엽':'♧'}</span>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function syncTheme(light=false){const view=surface.querySelector('.app-view');let bg='transparent',fg='#fff';if(view){if(view.classList.contains('chat-room')){bg='#b9cbd9';fg='#23343e'}else if(view.classList.contains('music-view')){bg='#0f1011';fg='#fff'}else if(view.classList.contains('photo-view')){bg='#080909';fg='#fff'}else if(view.classList.contains('bubble-view')){bg='#fcfaff';fg='#292331'}else if(light){bg=dark?'#181c1a':'#f5f5f5';fg=dark?'#fff':'#222'}else{bg='#080b0a';fg='#fff'}}$('#statusbar').style.color=fg;$('#statusbar').style.background=bg;$('#systemNav').style.color=fg;$('#systemNav').style.background=bg;$('#screen').classList.toggle('setting-dark',dark)}
function setSurface(html,{light=false}={}){surface.innerHTML=html;syncTheme(light)}
function lockPhone(){unlocked=false;screen='lock';pin='';pending=null;overlay.innerHTML='';history=[];renderLock()}
function legacyRenderLock(){setSurface(`<div class="lock-screen"><div class="lock-icon">${icon('lock')}</div><div class="lock-time"><span>01</span><span>00</span></div><div class="lock-date">10월 23일 금요일</div><button class="lock-notification" aria-label="신예찬 카카오톡 알림 열기" onclick="beginUnlock('yechan')"><div class="notice-top"><span><span class="kakao-mini">TALK</span> 카카오톡</span><span>지금</span></div><div class="notice-name">${CONTACTS.yechan.name}</div><div class="notice-message">엽아 잠이 안 온당...</div></button><button class="unlock-area" aria-label="잠금 해제" onclick="beginUnlock()"></button><div class="lock-bottom"><button aria-label="전화 바로가기" onclick="beginUnlock('phone')">${icon('phone')}</button><span>화면을 밀어 잠금을 해제하세요</span><button aria-label="카메라 바로가기" onclick="beginUnlock('camera')">${icon('camera')}</button></div></div>`);$('#systemNav').style.visibility='hidden'}
function beginUnlock(target=null){pending=target;pin='';screen='pin';renderPin()}
function renderPin(error=false){setSurface(`<div class="pin-screen"><h2>PIN 입력</h2><div class="pin-hint">${error?'PIN이 올바르지 않습니다. 다시 입력하세요.':'휴대전화의 잠금을 해제하려면 PIN을 입력하세요.'}</div><div class="pin-dots ${error?'shake':''}">${[0,1,2,3].map(i=>`<span class="pin-dot ${i<pin.length?'filled':''}"></span>`).join('')}</div><div class="keypad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map((n,i)=>n===''?'<span></span>':`<button aria-label="${n==='⌫'?'한 자리 지우기':n}" onclick="pinKey('${n}')">${n}<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ'][i]||' '}</small></button>`).join('')}</div><div class="pin-footer"><button onclick="toast('이 화면에서는 긴급전화를 걸 수 없습니다.')">긴급전화</button><button onclick="lockPhone()">취소</button></div></div>`)}
function pinKey(k){if(k==='⌫')pin=pin.slice(0,-1);else if(pin.length<4)pin+=k;if(pin.length===4){if(pin==='0613'){unlocked=true;$('#systemNav').style.visibility='visible';pending=null;goHome();queueIncomingCall();return}pin='';renderPin(true);return}renderPin()}
function baseGoHomeV3(){if(screen==='note'&&$('#noteEdit'))autoSaveNote();if(!unlocked){beginUnlock();return}screen='home';activeChat=null;overlay.innerHTML='';history=[];playerOpen=false;$('#systemNav').style.visibility='visible';setSurface(`<div class="home"><div class="home-top"><button class="weather-widget" onclick="openApp('weather')"><span class="weather-moon">☾</span><div class="degree">13°</div><small>서울특별시<br>맑음 · 최저 11° / 최고 20°</small><small style="margin-top:5px">10.23 오전 1:00</small></button><div class="mini-widgets"><button class="date-widget" onclick="openApp('calendar')">10월 23일 금요일<b>오늘도 좋은 하루</b></button><button class="schedule-widget" onclick="openApp('calendar')">오늘의 일정<b>첫 번째 공연 🎤</b><span style="font-size:8px;opacity:.7">LUCY CONCERT · DAY 1</span></button></div></div><form class="search-widget" onsubmit="homeSearch(event)"><span class="google-g">G</span><input aria-label="Google 검색" placeholder="" id="homeSearch"><span style="font-size:15px">♩</span><span style="font-size:18px">⌘</span></form><div class="home-apps">${['kakao','bubble','music','gallery','calendar','notes','youtube','settings','recorder','files','clock','contact'].map(id=>appButton(id,true)).join('')}</div><div class="dots"><b>●</b>●●</div><div class="dock">${['phone','messages','internet','camera'].map(id=>appButton(id)).join('')}</div><button class="drawer-button" aria-label="모든 앱 보기" onclick="renderDrawer()">⌃</button></div>`)}
function homeSearch(e){e.preventDefault();let q=$('#homeSearch').value.trim();if(q){window.open('https://www.google.com/search?q='+encodeURIComponent(q),'_blank','noopener');toast('새 탭에서 검색합니다.')}}
function renderDrawer(query=''){screen='drawer';setSurface(`<div class="drawer"><div class="app-grid" id="drawerGrid">${APPS.filter(a=>a[1].toLowerCase().includes(query.toLowerCase())).map(a=>appButton(a[0],true)).join('')}</div><div class="dots"><b>●</b>●●</div><div class="drawer-search"><input aria-label="앱 검색" placeholder="검색" value="${esc(query)}" oninput="filterApps(this.value)"><span>⋮</span></div></div>`)}
function filterApps(q){$('#drawerGrid').innerHTML=APPS.filter(a=>a[1].toLowerCase().includes(q.toLowerCase())).map(a=>appButton(a[0],true)).join('')}
function openApp(id){if(!unlocked){beginUnlock(id);return}if(screen!=='home'&&screen!=='drawer')history.push({screen,activeChat});screen=id;activeChat=null;overlay.innerHTML='';recent=recent.filter(a=>a!==id);recent.unshift(id);recent=recent.slice(0,7);playerOpen=false;renderApp(id)}
function header(title,right='',back=false){return `<header class="app-header">${back?`<button class="icon-btn" aria-label="뒤로" onclick="goBack()">${icon('back')}</button>`:''}<h2>${esc(title)}</h2>${right}</header>`}
function shell(title,body,right='',tabs='',cls=''){setSurface(`<section class="app-view ${cls}">${header(title,right)}<div class="app-content">${body}</div>${tabs}</section>`,{light:!['music-view','photo-view'].includes(cls)})}
function renderApp(id){const f={kakao:renderKakao,bubble:renderBubble,calendar:renderCalendar,music:renderMusic,notes:renderNotes,gallery:renderGallery,phone:renderPhone,contact:renderContacts,messages:renderSMS,clock:renderClock,calculator:renderCalculator,settings:renderSettings,recorder:renderRecorder,camera:renderCamera,files:renderFiles,internet:renderInternet,chrome:renderInternet,google:renderInternet,naver:renderInternet,youtube:renderYouTube,mail:renderMail,weather:renderWeather,maps:renderMaps,health:renderHealth,playstore:renderStore,store:renderStore,drive:renderDrive};(f[id]||renderFiles)()}
function goBack(){if(screen==='note'&&$('#noteEdit'))autoSaveNote();if(overlay.innerHTML){overlay.innerHTML='';return}if(screen==='pin'){lockPhone();return}if(!unlocked)return;if(activeChat){activeChat=null;renderKakao();return}if(screen==='music'&&playerOpen){playerOpen=false;if(currentPlaylist!==null)openPlaylist(currentPlaylist);else renderMusic();return}if(screen==='music'&&currentPlaylist!==null){renderMusic();return}if(screen==='photo'){screen='gallery';renderGallery();return}if(screen==='sms-thread'){screen='messages';renderSMS();return}if(screen==='record-detail'){screen='recorder';renderRecorder();return}if(screen==='locked-note'){screen='notes';renderNotes();return}if(screen==='note'){screen='notes';renderNotes();return}if(screen==='contact-detail'){screen='contact';renderContacts();return}if(screen==='call'){endCall();return}if(history.length){let h=history.pop();screen=h.screen;activeChat=h.activeChat;if(activeChat)renderChat();else renderApp(screen);return}goHome()}
function kakaoTabs(current='chat'){return `<nav class="app-tabs">${[['person','친구','friends'],['chat','채팅','chat'],['heart','업데이트','updates'],['more','더보기','more']].map(([ic,n,id])=>`<button class="${current===id?'active':''}" onclick="renderKakao('${id}')">${icon(ic)}${n}</button>`).join('')}</nav>`}
function renderKakao(tab='chat'){screen='kakao';activeChat=null;if(tab==='friends'){shell('친구',`<button class="chat-list-row" onclick="showSelfProfile()">${profile('self')}<div class="chat-details"><b>최상엽</b><p>오늘도 잘 부탁해요</p></div></button><div class="friends-section">즐겨찾기 1</div>${contactChatRow('yechan',true)}<div class="friends-section">친구 ${Object.keys(CONTACTS).length-1}</div>${Object.keys(CONTACTS).filter(id=>id!=='group').map(id=>contactChatRow(id,true)).join('')}`,'',kakaoTabs(tab),'kakao-view');return}if(tab==='more'){shell('더보기',`<div class="settings-account">${profile('self')}<div>최상엽<small>나의 카카오톡</small></div></div><div class="section-card"><button class="list-item" onclick="showSelfProfile()">내 프로필 보기<span>›</span></button><button class="list-item" onclick="toast('친구와의 대화는 이 기기에 저장됩니다.')">대화 저장 정보<span>›</span></button><button class="list-item" onclick="openApp('calendar')">캘린더<span>›</span></button></div>`,'',kakaoTabs(tab),'kakao-view');return}if(tab==='updates'){shell('업데이트',`<div class="social-post"><b>신예찬</b><p>내일 봐요 🎻<br>잘 자고 와야 돼 진짜로</p><small>10월 22일 오후 11:05</small></div><div class="social-post"><b>조원상</b><p>준비 끝 🎧</p><small>10월 22일 오후 10:12</small></div>`,'',kakaoTabs(tab),'kakao-view');return}shell('채팅',`<input class="search-input" placeholder="이름, 메시지 검색" aria-label="대화 검색" oninput="filterChats(this.value)"><div id="chatList">${Object.keys(CONTACTS).map(id=>contactChatRow(id)).join('')}</div>`,`<button class="icon-btn" aria-label="채팅 검색" onclick="document.querySelector('.search-input').focus()">${icon('search')}</button>`,kakaoTabs(),'kakao-view')}
function legacyContactChatRow(id,friend=false){const c=CONTACTS[id],last=chats[id]?.at(-1);return `<button class="chat-list-row" onclick="openChat('${id}')">${profile(id)}<div class="chat-details"><b>${esc(c.name)}</b><p>${esc(friend?c.status:(last?.[1]||c.last))}</p></div>${!friend?`<div class="chat-meta"><span>${last?.[2]?.replace('오전 ','').replace('오후 ','')||c.time}</span>${id==='yechan'&&!allRead?'<span class="unread">1</span>':''}</div>`:''}</button>`}
function filterChats(q){$('#chatList').innerHTML=Object.keys(CONTACTS).filter(id=>CONTACTS[id].name.includes(q)||chats[id].some(m=>m[1].includes(q))).map(id=>contactChatRow(id)).join('')}
function baseOpenChatV3(id){screen='kakao';activeChat=id;if(id==='yechan'){allRead=true;saveStore('allRead',true)}renderChat()}
function msgHTML(m,id){return `<div class="message ${m[0]?'mine':''}">${m[0]?'':profile(id)}<div class="msg-body">${m[0]?'':`<div class="sender-name">${esc(id==='group'?m[1].split(':')[0]:CONTACTS[id]?.name||'왈왈이')}</div>`}<div class="bubble-line"><div class="bubble">${esc(id==='group'&&!m[0]?m[1].replace(/^[^:]+:\s*/, ''):m[1])}</div><span class="msg-time">${esc(m[2]||'오전 1:00')}</span></div></div></div>`}
function renderChat(){const id=activeChat;if(!id)return;setSurface(`<section class="app-view chat-room"><header class="app-header"><button class="icon-btn" aria-label="채팅 목록으로" onclick="activeChat=null;renderKakao()">${icon('back')}</button><span class="chat-title">${esc(CONTACTS[id].name)}</span><button class="icon-btn" aria-label="대화 검색" onclick="searchConversation()">${icon('search')}</button><button class="icon-btn" aria-label="채팅방 메뉴" onclick="chatMenu()">${icon('more')}</button></header><div class="chat-scroll" id="chatScroll"><div class="chat-date">2026년 10월 22일 목요일</div>${(chats[id]||[]).map((m,i)=>`${m[2]?.startsWith('오전 12:59')&&i>0?'<div class="chat-date">2026년 10월 23일 금요일</div>':''}${msgHTML(m,id)}`).join('')}</div>${replyTimers[id]?'<div class="typing">메시지를 입력 중...</div>':''}<form class="composer" onsubmit="sendChatForm(event)"><button type="button" aria-label="메시지 첨부" onclick="chatAttachment()">＋</button><input id="chatInput" aria-label="카카오톡 메시지" placeholder="메시지 입력" autocomplete="off"><button type="button" aria-label="이모티콘" onclick="insertEmoji()">☺</button><button class="send-btn" aria-label="전송" type="submit">↑</button></form></section>`,{light:true});syncTheme(false);requestAnimationFrame(()=>{let el=$('#chatScroll');if(el)el.scrollTop=el.scrollHeight})}
function sendChatForm(e){e.preventDefault();const val=$('#chatInput').value.trim();if(val)sendChat(val)}
function legacySendChat(text){const id=activeChat;if(!id||!text.trim())return;chats[id].push([1,text,'오전 1:00']);saveStore('chats',chats);if(replyTimers[id])clearTimeout(replyTimers[id]);replyTimers[id]=setTimeout(()=>{const response=makeReply(id,text);chats[id].push([0,response,'오전 1:01']);delete replyTimers[id];saveStore('chats',chats);if(activeChat===id)renderChat();else toast(`${CONTACTS[id].short}: ${response}`)},1100+Math.random()*700);renderChat()}
function legacyMakeReply(id,text){if(id==='yechan'){if(/사랑|좋아|보고 싶|보고싶/.test(text))return '나도. 그래서 잠이 안 오나 봐 ㅋㅋㅋ 너 보고 싶어서';if(/갈까|갈게|가요|갈까요|문 열|기다려/.test(text))return '진짜 올 거야? 그럼 나 문 열어놓을게. 올 때 겉옷 입고 와';if(/잠|자요|자라|자야|잘 자/.test(text))return '자려고 했는데 자꾸 내일 생각나. 너랑 얘기 좀 하다가 자면 안 돼?';if(/떨|걱정|공연|잘할/.test(text))return '그치. 너 옆에 있으면 괜찮을 것 같아. 내일도 나 한 번씩 봐줘';if(/뭐|왜|무슨/.test(text))return '그냥 너 생각나서. 내일 보는데도 이상하지 ㅋㅋ';if(/형/.test(text))return '왜 그렇게 불러 ㅋㅋㅋ 보고 싶게. 너 아직 안 졸려?';if(/밥|먹|배고/.test(text))return '아까 네가 사 온 거 다 먹었어. 내일 끝나고도 같이 먹자';return ['이 시간에 너랑 얘기하니까 좋다. 자야 되는데 ㅋㅋ','엽아 근데 내일 끝나고 나랑 같이 가면 안 돼?','너 먼저 졸리면 자. 나는 조금만 더 있다가 잘게'][chats[id].filter(m=>m[0]).length%3]}if(id==='wonsang')return /예찬|형/.test(text)?'ㅋㅋㅋㅋ 나 아무 말도 안 했어 형. 내일 봐':'확인했어! 내일 맞춰보자 형. 얼른 자';if(id==='gwangil')return '형도 빨리 자 ㅋㅋㅋ 이따 봐. 내일 끝나고 고기 잊지 마';if(id==='group')return '조원상: 두 분 아직도 안 자는 거예요? ㅋㅋㅋ 내일 봐요';if(id.startsWith('manager'))return '넵 확인했어요! 푹 쉬고 이따 봐요 :)';return '네 확인했습니다. 감사합니다!'}
function insertEmoji(){const el=$('#chatInput');el.value+='☺';el.focus()}
function chatMenu(){overlay.innerHTML=`<div class="chat-menu"><button onclick="${activeChat==='group'?"showInfo('루시 (4)','신예찬 · 최상엽 · 조원상 · 신광일')":`viewContact('${activeChat}');overlay.innerHTML=''`}">프로필 보기</button><button onclick="editConversation()">대화 내용 편집</button><button onclick="overlay.innerHTML='';toast('채팅방 알림을 해제했습니다.')">알림 끄기</button><button onclick="overlay.innerHTML=''">닫기</button></div>`}
function editConversation(){const id=activeChat;overlay.innerHTML=`<div class="info-sheet" style="inset:75px 12px 65px;display:flex;flex-direction:column"><h3>대화 내용 편집</h3><p style="margin:0 0 10px">상엽: 내용 / 상대: 내용<br>한 줄에 메시지 하나씩 입력하세요.</p><textarea id="conversationEdit" style="flex:1;min-height:0;border:1px solid #ccd3c9;border-radius:12px;padding:12px;font-size:11px;line-height:1.8;resize:none">${esc(chats[id].map(m=>(m[0]?'상엽: ':'상대: ')+m[1]).join('\n'))}</textarea><button onclick="saveConversation('${id}')">저장</button><button style="margin-top:5px;background:transparent" onclick="overlay.innerHTML=''">취소</button></div>`}
function saveConversation(id){let text=$('#conversationEdit').value;let result=text.split('\n').filter(t=>t.trim()).map((t,i)=>[t.startsWith('상엽:' )?1:0,t.replace(/^(상엽|상대):\s*/,''),chats[id][i]?.[2]||'오전 1:00']);chats[id]=result;saveStore('chats',chats);overlay.innerHTML='';renderChat();toast('대화를 저장했습니다.')}
function searchConversation(){overlay.innerHTML=`<div class="info-sheet"><h3>대화 검색</h3><input id="convSearch" class="search-input" aria-label="대화에서 찾을 단어" placeholder="검색할 단어" oninput="findMessages(this.value)"><div id="convResults" style="max-height:260px;overflow:auto;font-size:12px;line-height:1.8">검색어를 입력하세요.</div><button onclick="overlay.innerHTML=''">닫기</button></div>`}
function findMessages(q){$('#convResults').innerHTML=q?chats[activeChat].filter(m=>m[1].includes(q)).map(m=>`<p>${m[0]?'상엽':esc(CONTACTS[activeChat].short)}: ${esc(m[1])}</p>`).join('')||'검색 결과가 없습니다.':'검색어를 입력하세요.'}
function legacyChatAttachment(){overlay.innerHTML='<div class="chat-menu"><button onclick="overlay.innerHTML=\'\';openApp(\'gallery\')">갤러리 열기</button><button onclick="overlay.innerHTML=\'\';insertEmoji()">이모티콘 넣기</button><button onclick="overlay.innerHTML=\'\'">닫기</button></div>'}
function showSelfProfile(){showInfo('최상엽','오늘도 잘 부탁해요\n\n프로필 뮤직: 사랑한 마음엔 죄가 없다 — 소란')}
function renderCalendar(day=selectedDay){selectedDay=day;const selected=EVENTS[day]||[];shell('캘린더',`<div class="calendar-top">2026년 10월</div><div class="calendar-grid">${['일','월','화','수','목','금','토'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:4},()=>'<span></span>').join('')}${Array.from({length:31},(_,i)=>{let d=i+1,dow=(d+3)%7;return `<button aria-label="10월 ${d}일" class="day-button ${day===d?'selected':''} ${dow===0?'sun':dow===6?'sat':''}" onclick="renderCalendar(${d})">${d}${EVENTS[d]?'<span class="event-dot"></span>':''}</button>`}).join('')}</div><div class="calendar-summary">10월 23일–25일 · LUCY CONCERT<br>함께하는 세 번의 밤 🎻</div><div class="section-label">10월 ${day}일 · 일정 ${selected.length}개</div><div class="event-list">${selected.length?selected.map(e=>`<div class="event-row"><span class="event-time">${e[0]}</span><div class="event-info">${e[1]}<small>${e[2]}</small></div></div>`).join(''):'<div class="empty-state">등록된 일정이 없습니다.</div>'}</div>`,`<button class="icon-btn" aria-label="오늘" onclick="renderCalendar(23)">${icon('calendar')}</button>`,`<nav class="app-tabs"><button class="active" onclick="renderCalendar(23)">월</button><button onclick="renderAgenda()">일정</button></nav>`)}
function renderAgenda(){shell('다가오는 일정',Object.keys(EVENTS).filter(d=>d>=23).map(d=>`<div class="section-label">10월 ${d}일</div><div class="section-card">${EVENTS[d].map(e=>`<button class="list-item" onclick="renderCalendar(${d})"><div>${e[1]}<small>${e[0]} · ${e[2]}</small></div>›</button>`).join('')}</div>`).join(''))}
function songLink(s){return s.id?'https://www.youtube.com/watch?v='+s.id:s.url||'https://music.youtube.com/search?q='+encodeURIComponent(s.query)}
let currentPlaylist=null;
function musicTabs(){return `<nav class="app-tabs"><button onclick="renderMusic()">${icon('home')}홈</button><button onclick="renderMusicSearch()">${icon('search')}검색</button><button class="active" onclick="renderMusic()">${icon('music')}보관함</button></nav>`}
function renderMusic(){screen='music';playerOpen=false;currentPlaylist=null;shell('Music',`<div class="music-chips"><button class="chip" onclick="renderMusic()">플레이리스트</button><button class="chip" onclick="renderAllSongs()">노래</button><button class="chip" onclick="renderMusicSearch()">검색</button></div><div class="library-heading"><small>LIBRARY</small><h3>나의 플레이리스트</h3><span>노래하는 날도, 그냥 듣는 날도.</span></div><div class="playlist-grid">${PLAYLISTS.map((p,i)=>`<button class="playlist-card" onclick="openPlaylist(${i})"><span class="playlist-cover" style="background:linear-gradient(145deg,${p.color},#273c35)"><small>CHOI SANG YEOP</small><b>${p.art}</b><span>PLAYLIST / ${String(i+1).padStart(2,'0')}</span></span><strong>${p.title}</strong><small>최상엽 · ${p.songs.length}곡</small></button>`).join('')}</div><div class="library-heading" style="padding-top:20px"><h3>최근 들은 음악</h3></div>${[0,1,2,8].map(i=>songRow(SONGS[i],i)).join('')}`,`<button class="icon-btn" aria-label="음악 검색" onclick="renderMusicSearch()">${icon('search')}</button>`,musicMini()+musicTabs(),'music-view')}
function musicMini(){return `<button class="music-mini" onclick="openPlayer(${currentSong})"><span>♫</span><div>${esc(SONGS[currentSong].title)}<small>${esc(SONGS[currentSong].artist)}</small></div><span>▷</span></button>`}
function openPlaylist(i){currentPlaylist=i;playerOpen=false;const p=PLAYLISTS[i];shell(p.title,`<div class="playlist-art" style="background:linear-gradient(135deg,${p.color},#273c35)"><span>CHOI SANG YEOP</span><b>${p.art}</b><span>MY PLAYLIST / ${String(i+1).padStart(2,'0')}</span></div><div class="playlist-info"><h3>${p.title}</h3>${p.subtitle}<br><span style="display:inline-block;margin-top:7px;font-size:10px">최상엽 · ${p.songs.length}곡</span></div><div class="playlist-actions"><button onclick="openPlayer(${p.songs[0]})">▶ 재생</button><button onclick="shufflePlaylist(${i})">⇄ 셔플</button></div><div class="song-list">${p.songs.map(id=>songRow(SONGS[id],id)).join('')}</div><div class="music-caption">${p.description}</div>`,`<button class="icon-btn" aria-label="보관함으로" onclick="renderMusic()">${icon('back')}</button>`,musicMini()+musicTabs(),'music-view')}
function shufflePlaylist(i){let p=PLAYLISTS[i];openPlayer(p.songs[Math.floor(Math.random()*p.songs.length)])}
function renderAllSongs(){currentPlaylist=null;shell('내 노래',SONGS.map(songRow).join(''),`<button class="icon-btn" aria-label="보관함으로" onclick="renderMusic()">${icon('back')}</button>`,musicTabs(),'music-view')}
function songRow(s,i){return `<button class="song-row" onclick="openPlayer(${i})"><span class="song-art">♫</span><div><b>${esc(s.title)}</b><small>${esc(s.artist)}</small></div><span>⋮</span></button>`}
function renderMusicSearch(){shell('음악 검색',`<input class="search-input" style="background:#282b29;color:white" aria-label="음악 검색어" placeholder="노래, 아티스트 검색" oninput="filterSongs(this.value)"><div id="songResults">${SONGS.map(songRow).join('')}</div>`,'','', 'music-view')}
function filterSongs(q){$('#songResults').innerHTML=SONGS.map((s,i)=>({s,i})).filter(({s})=>(s.title+s.artist).toLowerCase().includes(q.toLowerCase())).map(({s,i})=>songRow(s,i)).join('')||'<div class="empty-state">검색 결과가 없습니다.</div>'}
function adjacentSong(step){const queue=currentPlaylist!==null?PLAYLISTS[currentPlaylist].songs:SONGS.map((_,i)=>i);let pos=queue.indexOf(currentSong);openPlayer(queue[(Math.max(0,pos)+step+queue.length)%queue.length])}
function openPlayer(i){currentSong=(i+SONGS.length)%SONGS.length;playerOpen=true;const s=SONGS[currentSong];setSurface(`<section class="app-view music-view"><header class="app-header"><button class="icon-btn" aria-label="플레이리스트로" onclick="playerBack()">${icon('back')}</button><h2 style="font-size:13px;text-align:center">${currentPlaylist!==null?PLAYLISTS[currentPlaylist].title:'나의 음악'}</h2><button class="icon-btn" aria-label="좋아요" onclick="toast('좋아요한 음악에 추가했습니다.')">${icon('heart')}</button></header><div class="app-content music-player"><div class="playlist-art" style="background:linear-gradient(140deg,${s.color},#243d33)"><span>${esc(s.artist)}</span><b>${esc(s.title)}</b><span>MY PLAYLIST</span></div><h3 style="font-size:20px;margin:15px 0 6px">${esc(s.title)}</h3><div style="font-size:12px;color:#aaa">${esc(s.artist)}</div>${s.id?`<div id="embedSlot"><button class="player-link" style="width:100%;background:#eee;color:#222" onclick="startOfficialVideo()">▶ 공식 커버 영상 재생</button></div>`:`<a class="player-link" href="${esc(songLink(s))}" target="_blank" rel="noopener">${s.url?'공식 무대 보기 ↗':'YouTube Music에서 찾아 듣기 ↗'}</a>`}<div class="player-controls"><button aria-label="셔플" onclick="openPlayer(Math.floor(Math.random()*SONGS.length))">⇄</button><button aria-label="이전 곡" onclick="adjacentSong(-1)">▮◀</button><button class="play" aria-label="${s.id?'공식 영상 재생':'음악 링크 열기'}" onclick="${s.id?'startOfficialVideo()':'openSongLink()'}">▶</button><button aria-label="다음 곡" onclick="adjacentSong(1)">▶▮</button><button aria-label="반복" onclick="this.classList.toggle('repeat-on');toast(this.classList.contains('repeat-on')?'한 곡 반복을 선택했습니다.':'반복을 해제했습니다.')">↻</button></div><div class="music-caption">${s.id?(s.artist==='자장가수'?'자장가수 공개 커버 영상':'LUCY ISLAND 공식 커버 영상'):'외부 음악 서비스에서 재생됩니다.'}</div></div></section>`)}
function playerBack(){if(currentPlaylist!==null)openPlaylist(currentPlaylist);else renderMusic()}
function legacyStartOfficialVideo(){if(!SONGS[currentSong].id)return;$('#embedSlot').innerHTML=`<iframe class="music-embed" src="https://www.youtube.com/embed/${SONGS[currentSong].id}?autoplay=1" title="나랑 아니면 — LUCY ISLAND 공식 커버" allow="autoplay; encrypted-media; fullscreen" allowfullscreen></iframe>`;toast('영상이 차단되면 YouTube에서 열어주세요.');$('#embedSlot').insertAdjacentHTML('beforeend',`<a class="small-link" href="${songLink(SONGS[currentSong])}" target="_blank" rel="noopener">YouTube에서 열기 ↗</a>`)}
function openSongLink(){window.open(songLink(SONGS[currentSong]),'_blank','noopener')}
function renderNotes(){screen='notes';shell('모든 노트',`<div style="font-size:11px;color:#888;padding:0 21px 8px">${notes.length}개의 노트</div><div class="note-grid">${notes.map((n,i)=>`<button class="note-card" onclick="openNote(${i})"><h3>${esc(n.title)}</h3><p>${esc(n.body.slice(0,115))}</p><small>${n.date}</small></button>`).join('')}</div>`,`<button class="icon-btn" aria-label="새 노트" onclick="newNote()">${icon('plus')}</button>`)}
let editingNote=null;
function autoSaveNote(){if(editingNote!==null&&$('#noteEdit')){notes[editingNote].body=$('#noteEdit').value;saveStore('notes',notes)}}
function openNote(i){editingNote=i;screen='note';setSurface(`<section class="app-view">${header(notes[i].title,`<button class="note-save" onclick="saveNote(${i})">저장</button>`,true)}<textarea id="noteEdit" class="note-edit" aria-label="노트 내용">${esc(notes[i].body)}</textarea><div style="padding:0 22px 20px;font-size:10px;color:#888">${notes[i].date} · Samsung Notes</div></section>`,{light:true})}
function newNote(){notes.push({title:'새 노트',body:'',date:'10월 23일'});saveStore('notes',notes);openNote(notes.length-1)}
function saveNote(i){notes[i].body=$('#noteEdit').value;if(notes[i].title==='새 노트')notes[i].title=notes[i].body.split('\n')[0].slice(0,18)||'새 노트';saveStore('notes',notes);toast('노트를 저장했습니다.')}
const PHOTOS=[['guitar','합주실','10월 22일 오후 5:12'],['coffee','오는 길','10월 22일 오전 11:28'],['night','집 앞 하늘','10월 21일 오후 10:15'],['stage','무대','10월 20일 오후 6:04'],['flowers','길에서','10월 19일 오후 1:02'],['sky','산책','10월 18일 오후 5:22'],['guitar','기타','10월 18일 오후 2:12'],['coffee','잠깐 쉬는 중','10월 17일 오후 3:40'],['night','좋았던 밤','10월 16일 오후 11:01']];
function legacyRenderGallery(filter='all'){screen='gallery';let photos=filter==='fav'?[PHOTOS[2],PHOTOS[4],PHOTOS[8]]:PHOTOS;shell('사진',`<div class="album-pills"><button onclick="renderGallery()">전체</button><button onclick="renderGallery('fav')">♡ 즐겨찾기</button></div><div class="section-label" style="margin-top:0">2026년 10월</div><div class="gallery-grid">${photos.map(p=>`<button class="gallery-thumb" aria-label="${p[1]} 사진" onclick="openPhoto(${PHOTOS.indexOf(p)})"><img src="assets/${p[0]}.jpg" alt="${p[1]}" loading="lazy"></button>`).join('')}</div><div class="section-label">사진 ${photos.length}장</div>`,'',`<nav class="app-tabs"><button class="active" onclick="renderGallery()">사진</button><button onclick="renderAlbums()">앨범</button><button onclick="renderGallery('fav')">스토리</button></nav>`)}
function renderAlbums(){shell('앨범',`<div class="note-grid">${[['최근 항목','guitar'],['즐겨찾기','night'],['공연','stage'],['일상','coffee']].map((a,i)=>`<button onclick="renderGallery('${i===1?'fav':'all'}')" style="padding:0;text-align:left"><img src="assets/${a[1]}.jpg" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:20px"><div style="font-size:12px;padding:10px 4px">${a[0]}</div></button>`).join('')}</div>`)}
function legacyOpenPhoto(i){screen='photo';let p=PHOTOS[i];setSurface(`<section class="app-view photo-view">${header(p[2],`<button class="icon-btn" aria-label="즐겨찾기" onclick="this.style.color='#f78589';toast('즐겨찾기에 추가했습니다.')">${icon('heart')}</button>`,true)}<div class="app-content" style="display:grid;place-items:center"><img class="photo-large" src="assets/${p[0]}.jpg" alt="${p[1]}"></div><div class="photo-caption">${p[1]}<br><small>갤러리 분위기 이미지 · Unsplash</small></div><div class="app-tabs" style="background:#151817;border:0;color:#ddd"><button onclick="openPhoto(${(i+PHOTOS.length-1)%PHOTOS.length})">이전</button><button onclick="toast('원본 사진을 감상 중입니다.')">사진 정보</button><button onclick="openPhoto(${(i+1)%PHOTOS.length})">다음</button></div></section>`)}
function legacyRenderContacts(){screen='contact';shell('연락처',`<input class="search-input" aria-label="연락처 검색" placeholder="연락처 검색" oninput="filterContacts(this.value)"><div class="section-label">내 프로필</div><button class="chat-list-row" onclick="showSelfProfile()">${profile('self')}<div class="chat-details"><b>최상엽</b></div></button><div class="section-label">즐겨찾기</div>${contactRow('yechan')}<div class="section-label">연락처 ${Object.keys(CONTACTS).length-1}개</div><div id="contactList">${Object.keys(CONTACTS).filter(id=>id!=='group').sort((a,b)=>CONTACTS[a].name.localeCompare(CONTACTS[b].name,'ko')).map(contactRow).join('')}</div>`)}
function contactRow(id){return `<button class="chat-list-row" onclick="viewContact('${id}')">${profile(id)}<div class="chat-details"><b>${esc(CONTACTS[id].name)}</b></div></button>`}
function filterContacts(q){$('#contactList').innerHTML=Object.keys(CONTACTS).filter(id=>id!=='group'&&CONTACTS[id].name.includes(q)).map(contactRow).join('')}
function legacyViewContact(id){activeChat=null;screen='contact-detail';setSurface(`<section class="app-view">${header('연락처','',true)}<div class="app-content contact-details">${profile(id)}<h3>${esc(CONTACTS[id].name)}</h3><p class="profile-status">${esc(CONTACTS[id].status)}</p><div class="contact-actions"><button aria-label="전화" onclick="startCall('${id}')">${icon('phone')}</button><button aria-label="카카오톡 보내기" onclick="openChat('${id}')">${icon('chat')}</button><button aria-label="즐겨찾기" onclick="toast('즐겨찾기에 추가했습니다.')">${icon('heart')}</button></div><div class="section-card"><button class="list-item" onclick="openChat('${id}')"><div>카카오톡<small>메시지 보내기</small></div>›</button>${id==='yechan'?'<div class="list-item"><div>메모<small>커피는 디카페인 / 물 챙겨주기</small></div></div>':''}</div></div></section>`,{light:true})}
function legacyRenderPhone(tab='recent'){screen='phone';if(tab==='keypad'){shell('전화',`<div class="dial-number" id="dialNumber"></div><div class="dialpad">${[1,2,3,4,5,6,7,8,9,'*',0,'#'].map((n,i)=>`<button onclick="dialKey('${n}')">${n}<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ','','+',''][i]}</small></button>`).join('')}</div><button class="dial-call" aria-label="전화 걸기" onclick="startCall('unknown')">${icon('phone')}</button><button style="display:block;margin:auto;font-size:17px" aria-label="번호 한 자리 지우기" onclick="$('#dialNumber').textContent=$('#dialNumber').textContent.slice(0,-1)">⌫</button>`,'',phoneTabs(tab));return}shell('전화',`<div class="section-label">10월 22일</div>${[['yechan','오후 11:12 · 발신 · 12분 46초'],['yechan','오후 8:10 · 수신 · 8초'],['manager1','오후 5:23 · 수신 · 1분 12초'],['wonsang','오후 2:16 · 발신 · 43초'],['yechan','오전 11:29 · 수신 · 2분 13초']].map(([id,t])=>`<button class="chat-list-row" onclick="startCall('${id}')">${profile(id)}<div class="chat-details"><b>${CONTACTS[id].name}</b><p><span style="color:#58a779">↗</span> ${t}</p></div>${icon('phone')}</button>`).join('')}`,'',phoneTabs(tab))}
function phoneTabs(t){return `<nav class="app-tabs"><button class="${t==='keypad'?'active':''}" onclick="renderPhone('keypad')">키패드</button><button class="${t==='recent'?'active':''}" onclick="renderPhone()">최근 기록</button><button onclick="openApp('contact')">연락처</button></nav>`}
function dialKey(k){$('#dialNumber').textContent+=k}
function startCall(id){screen='call';activeChat=null;let name=CONTACTS[id]?.name||$('#dialNumber')?.textContent||'전화';setSurface(`<div class="call-screen"><div style="font-size:11px;opacity:.7">전화</div><h3>${esc(name)}</h3><p>연결 중...</p><div class="call-controls"><button aria-label="음소거" onclick="this.classList.toggle('on');toast('음소거 설정을 변경했습니다.')">${icon('recorder')}</button><button aria-label="키패드" onclick="toast('통화 화면입니다.')">▦</button><button aria-label="스피커" onclick="this.classList.toggle('on');toast('스피커 설정을 변경했습니다.')">${icon('volume')}</button></div><button class="hangup" aria-label="통화 종료" onclick="endCall()">${icon('phone')}</button></div>`)}
function legacyEndCall(){screen='phone';renderPhone();toast('통화를 종료했습니다.')}
function legacyRenderSMS(){shell('메시지',`<div class="section-label">문자 메시지</div><button class="chat-list-row" onclick="showInfo('택배 알림','[배송완료]\n주문하신 기타 스트링이 배송 완료되었습니다.\n문 앞 보관\n\n10월 21일 오후 2:31')"><span class="profile">택</span><div class="chat-details"><b>택배 알림</b><p>주문하신 물품이 배송 완료되었습니다.</p></div><span style="font-size:9px;color:#aaa">10.21</span></button><button class="chat-list-row" onclick="showInfo('예약 안내','[예약 확정]\n10월 26일 저녁 식사 · 2명\n\n예약자: 최상엽\n예약 시간은 추후 확인하기')"><span class="profile">예약</span><div class="chat-details"><b>예약 안내</b><p>10월 26일 예약이 확정되었습니다.</p></div><span style="font-size:9px;color:#aaa">10.19</span></button>`)}
function renderClock(tab='alarm'){screen='clock';let html='';if(tab==='alarm')html=alarms.map((a,i)=>`<div class="section-card"><div class="alarm-row"><div><div class="alarm-time"><small>오전</small>${['9:00','9:10','10:00'][i]}</div><div class="alarm-label">${['첫콘 늦지 말기','진짜 일어나','휴일 알람'][i]} · ${i<2?'금요일':'월요일'}</div></div><button class="toggle ${a?'on':''}" aria-label="${['9시','9시 10분','10시'][i]} 알람 ${a?'끄기':'켜기'}" onclick="toggleAlarm(${i})"></button></div></div>`).join('');if(tab==='world')html='<div class="section-card"><div class="alarm-row"><div>서울<div class="alarm-label">대한민국</div></div><div class="alarm-time">1:00</div></div><div class="alarm-row"><div>런던<div class="alarm-label">영국 · 8시간 느림</div></div><div class="alarm-time">17:00</div></div></div>';if(tab==='stopwatch')html=`<div class="stopwatch" id="swTime">${formatMS(stopwatchElapsed)}</div><div class="round-actions"><button onclick="resetSW()">초기화</button><button id="swBtn" onclick="toggleSW()">${stopwatchTimer?'정지':'시작'}</button></div>`;if(tab==='timer')html='<div class="timer-box"><input id="timerMinutes" type="number" min="1" max="180" value="5" aria-label="타이머 분"> 분<div class="stopwatch" id="timerTime">05:00</div><div class="round-actions"><button onclick="startTimer()">시작</button><button onclick="clearInterval(timerInterval);timerInterval=null;toast(\'타이머를 취소했습니다.\')">취소</button></div></div>';shell('시계',html,'',`<nav class="app-tabs">${[['alarm','알람'],['world','세계시각'],['stopwatch','스톱워치'],['timer','타이머']].map(([id,n])=>`<button class="${id===tab?'active':''}" onclick="renderClock('${id}')">${n}</button>`).join('')}</nav>`)}
function toggleAlarm(i){alarms[i]=!alarms[i];saveStore('alarms',alarms);renderClock()}
function formatMS(ms){return `${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(Math.floor(ms/10)%100).padStart(2,'0')}`}
function toggleSW(){if(stopwatchTimer){clearInterval(stopwatchTimer);stopwatchTimer=null;stopwatchElapsed=Date.now()-stopwatchStart;$('#swBtn').textContent='시작'}else{stopwatchStart=Date.now()-stopwatchElapsed;stopwatchTimer=setInterval(()=>{stopwatchElapsed=Date.now()-stopwatchStart;let el=$('#swTime');if(el)el.textContent=formatMS(stopwatchElapsed)},50);$('#swBtn').textContent='정지'}}
function resetSW(){clearInterval(stopwatchTimer);stopwatchTimer=null;stopwatchElapsed=0;renderClock('stopwatch')}
function startTimer(){clearInterval(timerInterval);let sec=Math.min(180,Math.max(1,Number($('#timerMinutes').value)||5))*60;const update=()=>{const el=$('#timerTime');if(el)el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;if(sec<=0){clearInterval(timerInterval);timerInterval=null;toast('타이머가 종료되었습니다.')}sec--};update();timerInterval=setInterval(update,1000)}
function renderCalculator(){shell('계산기',`<div class="calculator-display" id="calcDisplay">${esc(calc||'0')}</div><div class="calc-grid">${['C','⌫','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','±','0','.','='].map(k=>`<button class="${'=+-−×÷'.includes(k)?k==='='?'eq':'op':''}" onclick="calcKey('${k}')">${k}</button>`).join('')}</div>`)}
function calcKey(k){if(k==='C')calc='';else if(k==='⌫')calc=calc.slice(0,-1);else if(k==='±'){if(/^-?\d*\.?\d+$/.test(calc))calc=String(-Number(calc))}else if(k==='%'){if(/^-?\d*\.?\d+$/.test(calc))calc=String(Number(calc)/100)}else if(k==='='){try{let toks=calc.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').match(/\d*\.?\d+|[+*/-]/g)||[];let values=[],ops=[],prec={'+':1,'-':1,'*':2,'/':2};function run(){let b=values.pop(),a=values.pop(),o=ops.pop();values.push(o==='+'?a+b:o==='-'?a-b:o==='*'?a*b:a/b)}for(let i=0;i<toks.length;i++){let t=toks[i];if(!isNaN(Number(t)))values.push(Number(t));else if(t==='-'&&(i===0||isNaN(Number(toks[i-1])))){values.push(-Number(toks[++i]))}else{while(ops.length&&prec[ops.at(-1)]>=prec[t])run();ops.push(t)}}while(ops.length)run();calc=Number.isFinite(values[0])?String(Math.round(values[0]*1e10)/1e10):'오류'}catch{calc='오류'}}else{if(calc==='오류')calc='';calc+=k}$('#calcDisplay').textContent=calc||'0'}
function legacyRenderSettings(){shell('설정',`<div class="settings-account">${profile('self')}<div>최상엽<small>Samsung account</small></div></div><div class="section-card"><button class="list-item" onclick="renderConnections()"><span class="setting-dot">⌁</span><div>연결<small>Wi-Fi, 블루투스, 비행기 탑승 모드</small></div>›</button><button class="list-item" onclick="showInfo('소리 및 진동','소리 모드: 진동\n벨소리: Over the Horizon\n알림음: 기본 알림')"><span class="setting-dot" style="background:#8a6db4">♫</span><div>소리 및 진동</div>›</button><button class="list-item" onclick="showInfo('알림','카카오톡 · 켜짐\nbubble · 켜짐\n캘린더 · 켜짐')"><span class="setting-dot" style="background:#d78071">♧</span><div>알림</div>›</button></div><div class="section-card"><button class="list-item" onclick="toggleDark()"><span class="setting-dot" style="background:#56a4a2">☼</span><div>디스플레이<small>${dark?'다크':'라이트'} 모드 · 눌러서 변경</small></div><span class="toggle ${dark?'on':''}"></span></button><button class="list-item" onclick="toggleFold()"><span class="setting-dot" style="background:#6d9b74">▣</span><div>커버 화면<small>Fold7 펼치기 / 접기</small></div>›</button><button class="list-item" onclick="lockPhone()"><span class="setting-dot" style="background:#c6a669">♧</span><div>잠금화면<small>PIN · 0613</small></div>›</button></div><div class="section-card"><button class="list-item" onclick="showInfo('배터리','87%\n\n절전 모드: 꺼짐\n배터리 상태: 좋음\n\n충전기를 연결하지 않은 상태')"><span class="setting-dot" style="background:#6aab7f">▯</span><div>배터리<small>87% · 사용 가능</small></div>›</button><button class="list-item" onclick="showInfo('휴대전화 정보','최상엽의 Z Fold7\n\nGalaxy Z Fold7\n모델명: SM-F966N\n\nGalaxy Z Fold7')"><span class="setting-dot" style="background:#7c8a9b">ⓘ</span><div>휴대전화 정보</div>›</button></div>`)}
function renderConnections(){shell('연결',`<div class="section-card"><div class="wifi-row"><span>Wi-Fi</span><button class="toggle ${quickStates.wifi?'on':''}" aria-label="Wi-Fi 전환" onclick="quickStates.wifi=!quickStates.wifi;renderConnections()"></button></div>${quickStates.wifi?'<div class="wifi-row"><span>LUCY_STUDIO<small style="font-size:9px;display:block;color:#888">연결됨</small></span><span>⌁</span></div>':''}<div class="wifi-row"><span>블루투스</span><button class="toggle ${quickStates.bluetooth?'on':''}" aria-label="블루투스 전환" onclick="quickStates.bluetooth=!quickStates.bluetooth;renderConnections()"></button></div><div class="wifi-row"><span>비행기 탑승 모드</span><button class="toggle ${quickStates.airplane?'on':''}" aria-label="비행기 모드 전환" onclick="quickStates.airplane=!quickStates.airplane;renderConnections()"></button></div></div>`)}
function toggleDark(){dark=!dark;saveStore('dark',dark);renderSettings()}
function legacyRenderRecorder(){shell('음성 녹음',`<div class="section-card"><button class="list-item" onclick="toast('아직 음원이 연결되지 않은 녹음 메모입니다.')">${icon('recorder')}<div>합주_후렴_체크<small>10월 22일 · 녹음 메모</small></div>▷</button><button class="list-item" onclick="showInfo('멘트 연습','첫 공연 와주셔서 감사합니다.\n끝까지 같이 즐겨주세요.\n\n— 메모된 연습 문구')">${icon('recorder')}<div>멘트 연습<small>10월 21일 · 텍스트 메모</small></div>›</button></div><div class="recorder-circle"><div class="record-wave">${[14,24,40,28,50,36,21,43,29,18].map((h,i)=>`<i style="height:${h}px;animation-delay:${i*.13}s;animation-play-state:${recording?'running':'paused'}"></i>`).join('')}</div></div><div class="recording-name" id="recordTime">${String(Math.floor(recordSecs/60)).padStart(2,'0')}:${String(recordSecs%60).padStart(2,'0')}</div><div class="round-actions"><button onclick="toggleRecord()" style="color:#d04861">${recording?'■ 종료':'● 연습 타이머'}</button></div><div class="music-caption">마이크를 사용하지 않는 연습 시간 기록</div>`)}
function toggleRecord(){recording=!recording;if(recording){recordSecs=0;recordTimer=setInterval(()=>{recordSecs++;if($('#recordTime'))$('#recordTime').textContent=`${String(Math.floor(recordSecs/60)).padStart(2,'0')}:${String(recordSecs%60).padStart(2,'0')}`},1000)}else{clearInterval(recordTimer);toast(`${recordSecs}초 동안 연습했습니다.`)}renderRecorder()}
