function renderInternet(){shell(screen==='naver'?'NAVER':screen==='chrome'?'Chrome':'인터넷',`<form class="browser-bar" onsubmit="webSearch(event)"><span>⌕</span><input id="webInput" aria-label="주소 또는 검색어" placeholder="검색어 또는 URL 입력"><button type="submit">↵</button></form><div class="browser-start"><h3>${screen==='naver'?'NAVER':'빠른 실행'}</h3><div class="browser-bookmarks">${[['LUCY','L','https://www.youtube.com/@LUCYISLAND'],['YouTube','▶','https://www.youtube.com/'],['Google','G','https://www.google.com/'],['네이버','N','https://www.naver.com/'],['YouTube Music','♫','https://music.youtube.com/'],['지도','⌖','https://map.naver.com/']].map(([n,s,u])=>`<a class="bookmark" href="${u}" target="_blank" rel="noopener"><span>${s}</span>${n}</a>`).join('')}</div></div><div class="section-label">최근 검색</div><div class="section-card">${['공연 전 목 관리','디카페인 커피 밤에 마셔도 되나요','합주실 근처 국밥','잠 안 올 때 듣기 좋은 노래'].map(q=>`<button class="list-item" onclick="searchWeb('${q}')">${icon('clock')}<div>${q}</div>↗</button>`).join('')}</div>`)}
