function legacyYTAvatar(c,size=''){return `<span class="yt-avatar" style="background:${c.color};${size}">${c.mark}</span>`}
function legacyYTVideoCard(v){const c=YT_CHANNELS[v.channel];return `<button class="yt-video" onclick="openYTVideo('${v.id}')"><span class="yt-thumbnail"><img src="assets/${v.channel===0?'stage':'guitar'}.jpg" alt="공연 및 악기 분위기 이미지" loading="lazy"><span class="yt-thumb-label">${esc(v.title)}</span><span class="yt-play">▶</span></span><span class="yt-video-info">${ytAvatar(c)}<span><b>${esc(v.title)}</b><small>${esc(v.sub)}</small></span><span>⋮</span></span></button>`}
function legacyRenderYouTube(tab='home'){screen='youtube';ytCurrentTab=tab;let body='';if(tab==='subscriptions'){body=`<div class="yt-channel-strip">${YT_CHANNELS.slice(0,4).map((c,i)=>`<button onclick="openYTChannel(${i})">${ytAvatar(c)}<small>${c.label}</small></button>`).join('')}</div><div class="section-label">내 구독 채널 · 4</div><div class="section-card">${YT_CHANNELS.slice(0,4).map((c,i)=>`<button class="yt-channel-row" onclick="openYTChannel(${i})">${ytAvatar(c)}<span><b>${c.label}</b><small>${c.name===c.label?c.handle:c.name+' · '+c.handle}</small></span><span class="yt-subscribed">구독중</span></button>`).join('')}</div><div class="section-label">구독 채널에서</div>${YT_VIDEOS.slice(0,3).map(ytVideoCard).join('')}`}else if(tab==='you'){let c=YT_CHANNELS[4];body=`<div class="yt-own">${ytAvatar(c,'width:67px;height:67px;font-size:25px')}<div><h3>최상엽엽</h3><small>@Yeopx2</small><button onclick="openYTChannel(4)">내 채널 보기 ›</button></div></div><div class="yt-own-tools"><button onclick="openYTChannel(4)">채널 보기</button><button onclick="renderYouTube('subscriptions')">구독 채널</button></div><div class="section-label">최근 본 동영상</div>${YT_VIDEOS.slice(1,4).map(ytVideoCard).join('')}<div class="section-label">재생목록</div><div class="section-card"><button class="list-item" onclick="openApp('music')">♫ <div>내 음악 플레이리스트<small>커버 · 자주 듣는 노래 · 추천곡</small></div>›</button></div>`}else{body=`<div class="music-chips"><button class="chip" onclick="renderYouTube()">전체</button><button class="chip" onclick="openApp('music')">음악</button><button class="chip" onclick="renderYouTube('subscriptions')">구독 채널</button></div>${YT_VIDEOS.map(ytVideoCard).join('')}`}shell('YouTube',body,`<button class="icon-btn" aria-label="유튜브 검색" onclick="searchYouTube()">${icon('search')}</button><button class="icon-btn" aria-label="내 유튜브 계정" onclick="renderYouTube('you')"><span class="yt-small-account">엽</span></button>`,ytTabs(tab),'youtube-view')}
function openYTChannel(i){const c=YT_CHANNELS[i];shell(c.label,`<div class="yt-banner" style="background:linear-gradient(130deg,${c.color},#233c33)">${c.label}</div><div class="yt-channel-profile">${ytAvatar(c,'width:66px;height:66px;font-size:26px')}<h3>${c.name}</h3><small>${c.handle}</small><p>${c.description}</p>${i<4?'<div class="yt-subscribed-wide">✓ 구독중</div>':'<div class="yt-subscribed-wide">내 채널</div>'}<a class="yt-external" href="${c.url}" target="_blank" rel="noopener">YouTube 채널 열기 ↗</a></div><div class="section-label">동영상</div>${YT_VIDEOS.filter(v=>v.channel===i).map(ytVideoCard).join('')||`<div class="section-card"><a class="list-item" style="text-decoration:none" href="${c.url}" target="_blank" rel="noopener"><div>채널 동영상 보기<small>${c.name}의 YouTube 채널로 이동합니다.</small></div>↗</a></div>`}`,`<button class="icon-btn" aria-label="유튜브로 돌아가기" onclick="renderYouTube(ytCurrentTab)">${icon('back')}</button>`,ytTabs(ytCurrentTab),'youtube-view')}
function openYTVideo(id){const v=YT_VIDEOS.find(v=>v.id===id);shell('동영상',`<div class="yt-watch"><iframe src="https://www.youtube.com/embed/${id}" title="${esc(v?.title||'YouTube 영상')}" allow="autoplay; encrypted-media; fullscreen" allowfullscreen></iframe><h3>${esc(v?.title||'YouTube 영상')}</h3><p>${esc(v?.sub||'')}</p><a class="yt-external" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">YouTube에서 보기 ↗</a></div>`,`<button class="icon-btn" aria-label="유튜브 목록으로" onclick="renderYouTube(ytCurrentTab)">${icon('back')}</button>`,ytTabs(ytCurrentTab),'youtube-view')}
function searchYouTube(){overlay.innerHTML=`<div class="info-sheet"><h3>YouTube 검색</h3><form onsubmit="event.preventDefault();window.open('https://www.youtube.com/results?search_query='+encodeURIComponent(document.querySelector('#ytSearch').value),'_blank','noopener')"><input id="ytSearch" class="search-input" aria-label="유튜브 검색어" placeholder="YouTube 검색"><button type="submit">검색</button></form><button onclick="overlay.innerHTML=''">닫기</button></div>`}
function renderMail(){shell('Gmail',`<input class="search-input" aria-label="메일 검색" placeholder="메일 검색" oninput="$('#mailList').style.display='공연 큐시트'.includes(this.value)?'block':'none'"><div class="section-label">기본</div><div id="mailList"><button class="chat-list-row" onclick="openMail()"><span class="profile" style="background:#deebe1">M</span><div class="chat-details"><b>미스틱 공연팀</b><p>[LUCY] 공연 큐시트 최종본 전달드립니다.</p><p>안녕하세요. 수정 내용 확인 부탁드립니다.</p></div><span style="font-size:9px">10.22</span></button></div>`)}
function openMail(){shell('공연 큐시트',`<div class="mail-body">미스틱 공연팀\n10월 22일 오후 8:12\n\n안녕하세요.\n공연 큐시트 최종본 전달드립니다.\n\n멘트 구간과 동선 변경 사항을 확인 부탁드립니다.\n개인 장비는 출발 전에 한 번 더 확인해주세요.\n\n감사합니다.\n공연팀 드림</div><button class="list-item" onclick="showCueSheet()">${icon('files')}<div>CONCERT_큐시트_최종.txt<small>첨부 파일 보기</small></div>›</button>`)}
function renderWeather(){shell('날씨',`<div class="weather-full"><div>서울특별시</div><div class="degree">13°</div><div style="font-size:25px">☾</div><p style="font-size:12px">맑음</p><div style="font-size:11px;color:#777">최고 20° · 최저 11°</div></div><div class="section-card"><div class="weather-hours">${['지금','02시','03시','04시','05시'].map((s,i)=>`<div>${s}<br>☾<br>${13-Math.floor(i/2)}°</div>`).join('')}</div></div><div class="music-caption">10월 23일 새벽의 시나리오 날씨</div>`)}
function renderMaps(){shell('지도',`<div class="map-search">⌕ 공연장 가는 길</div><div class="map-surface"><div class="map-pin">⌖<small>공연 준비</small></div></div><div class="section-card"><button class="list-item" onclick="window.open('https://map.naver.com/','_blank','noopener')"><div>네이버 지도에서 찾기<small>새 탭에서 지도를 엽니다.</small></div>↗</button></div>`)}
function renderHealth(){shell('Samsung Health',`<div class="health-steps">8,613</div><div class="health-sub">오늘의 걸음 · 목표 10,000걸음</div><div class="health-bars">${[50,80,65,95,82,112,92].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="section-card"><div class="list-item"><div>이번 주 활동<small>합주하고 돌아오는 길도 차곡차곡</small></div>♡</div><div class="list-item"><div>수면<small>이제 휴대폰을 내려놓고 쉬어볼까요?</small></div>☾</div><div class="list-item"><div>물<small>6잔 · 1,200 mL</small></div>♧</div></div>`)}
function renderStore(){shell(screen==='store'?'Galaxy Store':'Play 스토어',`<div class="section-label">설치된 앱</div><div class="section-card">${['kakao','bubble','music','contact'].map(id=>`<button class="list-item" onclick="openApp('${id}')"><span class="app-icon ${id}" style="width:38px;height:38px;border-radius:12px">${appIcon(id)}</span><div>${APPS.find(a=>a[0]===id)[1]}<small>설치됨</small></div>열기</button>`).join('')}</div><div class="music-caption">휴대폰 안에 설치된 앱을 열어보세요.</div>`)}
function renderDrive(){shell('Drive',`<div class="section-label">내 드라이브</div><div class="section-card"><button class="list-item" onclick="showCueSheet()">${icon('files')}<div>LUCY_CONCERT<small>공유 폴더 · 공연 준비</small></div>›</button><button class="list-item" onclick="openApp('notes')">${icon('notes')}<div>개인 메모<small>노트 ${notes.length}개</small></div>›</button></div>`)}
function legacyRenderBubble(tab=bubbleTab){bubbleTab=tab;screen='bubble';const tabs=`<nav class="app-tabs bubble-tabs"><button class="${tab==='chat'?'active':''}" onclick="renderBubble('chat')">${icon('chat')}메시지</button><button class="${tab==='fans'?'active':''}" onclick="renderBubble('fans')">${icon('heart')}답장함</button><button class="${tab==='profile'?'active':''}" onclick="renderBubble('profile')">${icon('person')}MY</button></nav>`;if(tab==='fans'){shell('bubble',`<div class="bubble-mode">ARTIST · 받은 답장</div><div class="section-label">왈왈이들이 보낸 답장</div>${bubble.filter(m=>!m[0]).slice().reverse().map(m=>`<div class="fan-reply"><span>왈왈이</span><p>${esc(m[1])}</p><small>${m[2]}</small></div>`).join('')}`,'',tabs,'bubble-view');return}if(tab==='profile'){shell('bubble',`<div class="bubble-mode">ARTIST ACCOUNT</div><div class="contact-details">${profile('self')}<h3>상엽 · LUCY</h3><p class="profile-status">오늘도 잘 부탁해요 🐶</p></div><div class="section-card"><div class="list-item"><div>아티스트 닉네임<small>상엽</small></div></div><div class="list-item"><div>나의 메시지<small>왈왈이들과 함께하는 하루</small></div></div><button class="list-item" onclick="showInfo('bubble 안내','아티스트 프로필 및 메시지 설정')">앱 정보 ›</button></div>`,'',tabs,'bubble-view');return}setSurface(`<section class="app-view bubble-view"><header class="app-header"><h2>bubble <span style="font-size:10px;font-weight:400;color:#9e85be">for LUCY</span></h2><button class="icon-btn" aria-label="버블 프로필" onclick="renderBubble('profile')">${icon('person')}</button></header><div class="bubble-mode">ARTIST · 왈왈이에게</div><div class="chat-scroll" id="bubbleScroll"><div class="chat-date">2026년 10월 22일 목요일</div>${bubble.map(m=>`<div class="message ${m[0]?'mine':''}">${m[0]?'':'<span class="fan-avatar">♡</span>'}<div class="msg-body">${m[0]?'':'<div class="sender-name">왈왈이의 답장</div>'}<div class="bubble-line"><div class="bubble">${esc(m[1])}</div><span class="msg-time">${m[2]}</span></div></div></div>`).join('')}</div><div class="quick-replies"><button onclick="sendBubble('내일 만나요. 잘 자요 왈왈이들')">잘 자요 왈왈이들</button><button onclick="sendBubble('첫콘 준비 다 됐어요?')">첫콘 준비 다 됐어요?</button></div><form class="composer" onsubmit="sendBubbleForm(event)"><span style="color:#9d83bf;padding:0 3px">♡</span><input aria-label="버블 메시지 작성" id="bubbleInput" placeholder="왈왈이들에게 메시지 보내기" autocomplete="off"><button class="send-btn" aria-label="버블 전송">↑</button></form>${tabs}</section>`,{light:true});requestAnimationFrame(()=>{if($('#bubbleScroll'))$('#bubbleScroll').scrollTop=$('#bubbleScroll').scrollHeight})}
function sendBubbleForm(e){e.preventDefault();let t=$('#bubbleInput').value.trim();if(t)sendBubble(t)}
function sendBubble(t){bubble.push([1,t,'오전 1:00']);saveStore('bubble',bubble);renderBubble('chat');lastBubbleReply++;let round=lastBubbleReply;setTimeout(()=>{let responses=/잘 자|자요|굿나잇/.test(t)?['상엽이도 잘 자요. 내일 봐 🫶','우리 이제 진짜 잘게 ㅋㅋㅋ']:['우리 준비 다 됐어요!! 상엽이는?','무리하지 말고 푹 쉬어요 💛'];responses.forEach(r=>bubble.push([0,r,'오전 1:01']));saveStore('bubble',bubble);if(screen==='bubble')renderBubble(bubbleTab);else toast('bubble에 새로운 답장이 도착했습니다.')},1400)}
function openQuick(){overlay.innerHTML=`<section class="quick-panel"><div class="quick-head"><span>10월 23일 금요일</span><div><button aria-label="전원" onclick="lockPhone()">⏻</button><button aria-label="설정" onclick="overlay.innerHTML='';openApp('settings')">⚙</button></div></div><div class="quick-main"><button class="quick-tile ${quickStates.wifi?'on':''}" onclick="quickToggle('wifi')">${icon('wifi')}<span>Wi-Fi<small style="display:block;font-size:8px">${quickStates.wifi?'LUCY_STUDIO':'꺼짐'}</small></span></button><button class="quick-tile ${quickStates.bluetooth?'on':''}" onclick="quickToggle('bluetooth')"><span style="font-size:25px">ᛒ</span><span>블루투스</span></button></div><div class="quick-circles">${[['sound','♫','소리'],['rotate','↻','자동 회전'],['airplane','✈','비행기 모드'],['torch','ϟ','손전등'],['location','⌖','위치'],['saving','▯','절전 모드'],['link','▣','Windows 연결'],['capture','▧','화면 캡처']].map(([id,ic,n])=>`<button class="${quickStates[id]?'on':''}" onclick="quickToggle('${id}')"><span>${ic}</span>${n}</button>`).join('')}</div><div class="slider-panel"><span>☼</span><input type="range" aria-label="밝기" value="${Math.round((Number($('#screen').dataset.brightness)||1)*100)}" min="45" max="100" oninput="setBrightness(this.value)"><span>☾</span></div><div class="slider-panel"><span>♫</span><input type="range" aria-label="미디어 음량" min="0" max="100" value="45" oninput="toast('미디어 음량 '+this.value+'%')"></div><div class="quick-now"><small>YouTube Music</small><b>${SONGS[currentSong].title}</b><div class="quick-track-controls"><button onclick="currentSong=(currentSong+SONGS.length-1)%SONGS.length;openQuick()">▮◀</button><button onclick="overlay.innerHTML='';openApp('music');openPlayer(currentSong)">▷</button><button onclick="currentSong=(currentSong+1)%SONGS.length;openQuick()">▶▮</button></div></div><button class="quick-notice" onclick="overlay.innerHTML='';unlocked?openChat('yechan'):beginUnlock('yechan')"><div style="font-size:9px;color:#72816e;margin-bottom:6px"><span class="kakao-mini">TALK</span> 카카오톡 · 오전 1:00</div><b style="font-size:11px">${CONTACTS.yechan.name}</b><div style="margin-top:4px">엽아 잠이 안 온당...</div></button><div class="quick-bottom"><button onclick="toast('기기에 연결된 항목이 없습니다.')">Smart View</button><button onclick="toast('SmartThings 기기 제어')">기기 제어</button></div><button class="quick-close" onclick="overlay.innerHTML=''">닫기 ⌃</button></section>`}
function quickToggle(id){if(id==='capture'){toast('화면 캡처 효과를 실행했습니다.');$('#screen').animate([{opacity:.4},{opacity:1}],250);return}if(id==='link'){toast('연결된 PC가 없습니다.');return}quickStates[id]=!quickStates[id];if(id==='torch')$('#device').classList.toggle('torch-on',quickStates.torch);openQuick()}
function setBrightness(v){$('#screen').dataset.brightness=v/100;surface.style.filter=`brightness(${v/100})`}
function recentApps(){if(!unlocked)return;overlay.innerHTML='';screen='recents';setSurface(`<div class="recents"><div style="font-size:11px;opacity:.7">최근 사용한 앱</div><div class="recent-list">${(recent.length?recent:['kakao','music','calendar']).map(id=>`<button class="recent-card ${id==='kakao'?'chat-preview':''}" onclick="openApp('${id}')"><span class="app-icon ${id}" style="width:35px;height:35px;border-radius:12px;margin:0 auto 18px">${appIcon(id)}</span><h3>${APPS.find(a=>a[0]===id)?.[1]||'앱'}</h3>${id==='kakao'?'<p>예찬이형♥</p><p>엽아<br>잠이 안 온당...</p>':id==='music'?'<p>늦은 밤, 자주 듣는 노래</p><p>TOUCH MY BODY<br>샘김 (SAM KIM)</p>':id==='calendar'?'<p>10월 23일 금요일</p><p>LUCY CONCERT · DAY 1<br>첫 번째 공연</p>':id==='bubble'?'<p>ARTIST · 왈왈이에게</p><p>잘 자요. 이따 만나</p>':'<p>이어서 살펴보기</p>'}</button>`).join('')}</div><button class="recent-close" onclick="recent=[];goHome();toast('최근 앱을 모두 닫았습니다.')">모두 닫기</button><div class="dock" style="margin-top:15px">${['phone','kakao','music','camera'].map(id=>appButton(id)).join('')}</div></div>`)}
function legacyToggleFold(){$('#device').classList.toggle('folded-open');$('#foldBtn').innerHTML=$('#device').classList.contains('folded-open')?'<span>▯</span> 접어 보기':'<span>▣</span> 펼쳐 보기';toast($('#device').classList.contains('folded-open')?'넓은 화면으로 펼쳤습니다.':'커버 화면으로 돌아왔습니다.')}
function showInfo(title,text){overlay.innerHTML=`<div class="info-sheet"><h3>${esc(title)}</h3><p style="white-space:pre-wrap">${esc(text)}</p><button onclick="overlay.innerHTML=''">확인</button></div>`}
function legacyShowHelp(){showInfo('상엽의 Galaxy','잠금화면의 알림을 누르거나 위로 밀어 PIN 0613을 입력하세요.\n\n카카오톡에서는 답장을 보내면 반응이 이어집니다. 채팅방 메뉴에서 대화를 편집할 수도 있습니다.\n\n상단을 누르면 빠른 설정, 하단 왼쪽 버튼을 누르면 최근 앱이 열립니다. 홈 화면을 위로 밀면 모든 앱을 볼 수 있습니다.\n\n설정 → 커버 화면에서 폴드를 펼칠 수 있습니다.\n\n')}
let touchY=0;surface.addEventListener('touchstart',e=>{touchY=e.touches[0].clientY},{passive:true});surface.addEventListener('touchend',e=>{const dy=e.changedTouches[0].clientY-touchY;if(screen==='lock'&&dy< -50)beginUnlock();else if(screen==='home'&&dy< -65)renderDrawer();else if(screen==='home'&&dy>65)openQuick()},{passive:true});
document.addEventListener('keydown',e=>{if(screen==='pin'&&!overlay.innerHTML){if(/^\d$/.test(e.key))pinKey(e.key);if(e.key==='Backspace')pinKey('⌫')}if(e.key==='Escape')goBack()});

